mapper.select:
select t.*,IFNULL(t2.CALENDAR,'BEJ') CALENDAR from TB_19_IR_CURVE t LEFT JOIN TB_19_CURVE_ALL_INFO t1 on t.CURVE_CODE=t1.CURVE_CODE LEFT JOIN
TB_17_CURRENCY_CALENDAR t2 on t1.CURRENCY_CODE=t2.CURRENCY

     and t.DATA_DATE = #{dataDate}

select DATA_DATE, CURVE_CODE,TERM_CODE, RATE YIELD_RATE,TERM_DAYCOUNT,FREQ TERM_FRQ,
CASE WHEN FREQ='0D' THEN 'ZERO' ELSE 'SWAP' END as TERM_TYPE,'Calpek' CALENDAR from TB_19_BOND_CURVE

     and DATA_DATE = #{dataDate}

select t.*,IFNULL(t2.CALENDAR,'BEJ') CALENDAR  from TB_19_FX_CURVE t LEFT JOIN TB_19_CURVE_ALL_INFO t1 on t.CURVE_CODE=t1.CURVE_CODE LEFT JOIN
TB_17_CURRENCY_CALENDAR t2 on t1.CURRENCY_CODE=t2.CURRENCY

     and t.DATA_DATE = #{dataDate}
